SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF COL_LENGTH('SOSRequests','RequestKey') IS NULL ALTER TABLE SOSRequests ADD RequestKey UNIQUEIDENTIFIER NULL, AssignedResponderId UNIQUEIDENTIFIER NULL, AcknowledgedAt DATETIME2 NULL, ResolutionNote NVARCHAR(2000) NULL;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('SOSRequests') AND name='UX_SOS_RequestKey') EXEC(N'CREATE UNIQUE INDEX UX_SOS_RequestKey ON SOSRequests(CommunityId,UserId,RequestKey) WHERE RequestKey IS NOT NULL');
IF OBJECT_ID('SOSTargets','U') IS NULL CREATE TABLE SOSTargets(SOSId UNIQUEIDENTIFIER NOT NULL REFERENCES SOSRequests(Id),UserId UNIQUEIDENTIFIER NOT NULL REFERENCES Users(Id),NotificationId UNIQUEIDENTIFIER NOT NULL,TargetedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),AcknowledgedAt DATETIME2 NULL,PRIMARY KEY(SOSId,UserId));
IF OBJECT_ID('ChatReferenceRequests','U') IS NULL CREATE TABLE ChatReferenceRequests(CommunityId UNIQUEIDENTIFIER NOT NULL,UserId UNIQUEIDENTIFIER NOT NULL,RequestKey UNIQUEIDENTIFIER NOT NULL,ConversationId UNIQUEIDENTIFIER NOT NULL,ListingId UNIQUEIDENTIFIER NOT NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),PRIMARY KEY(CommunityId,UserId,RequestKey));
IF COL_LENGTH('Communities','CurrencyCode') IS NULL ALTER TABLE Communities ADD CurrencyCode CHAR(3) NULL;
EXEC(N'UPDATE c SET CurrencyCode=COALESCE((SELECT TOP 1 CurrencyCode FROM MemberDuesPlans p WHERE p.CommunityId=c.Id ORDER BY p.CreatedAt DESC),CASE WHEN UPPER(c.Country) IN(''GB'',''UK'',''UNITED KINGDOM'') THEN ''GBP'' WHEN UPPER(c.Country) IN(''NG'',''NIGERIA'') THEN ''NGN'' ELSE NULL END) FROM Communities c WHERE CurrencyCode IS NULL');
IF COL_LENGTH('NotificationDeliveries','AttemptCount') IS NULL ALTER TABLE NotificationDeliveries ADD AttemptCount INT NOT NULL CONSTRAINT DF_NotificationDeliveries_Attempts DEFAULT 0;
COMMIT;
